import { Button as ButtonPrimitive } from "@base-ui/react/button"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const buttonVariants = cva(
  "group/button inline-flex shrink-0 items-center justify-center gap-2 whitespace-nowrap rounded-[10px] border border-transparent bg-clip-padding text-sm font-medium transition-all duration-200 ease-out outline-none select-none focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 active:scale-[0.98] disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90 shadow-sm",
        primary: "bg-primary text-primary-foreground hover:bg-primary/90 shadow-sm",
        outline: "border border-input bg-background hover:bg-accent hover:text-accent-foreground",
        secondary: "bg-secondary text-foreground border border-border shadow-[var(--shadow-xs)] hover:bg-secondary/80 hover:border-strong",
        ghost: "hover:bg-accent hover:text-accent-foreground",
        quiet: "bg-transparent text-foreground hover:bg-accent",
        gold: "bg-gold text-[var(--reader-ink)] hover:bg-gold-strong",
        inverse: "bg-background text-jade-900 hover:bg-white",
        destructive: "bg-destructive text-destructive-foreground hover:bg-destructive/90 shadow-sm",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-8 gap-1.5 px-2.5 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2",
        xs: "h-6 gap-1 rounded-[min(var(--radius-md),10px)] px-2 text-xs in-data-[slot=button-group]:rounded-lg has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: "px-[12px] py-[7px] text-sm min-h-[34px] rounded-[var(--radius-field)]",
        md: "px-[18px] py-[11px] text-base min-h-[44px] rounded-[var(--radius-field)]",
        lg: "px-[24px] py-[14px] text-lg min-h-[52px] rounded-[var(--radius-field)]",
        icon: "size-8",
        "icon-xs":
          "size-6 rounded-[min(var(--radius-md),10px)] in-data-[slot=button-group]:rounded-lg [&_svg:not([class*='size-'])]:size-3",
        "icon-sm":
          "size-7 rounded-[min(var(--radius-md),12px)] in-data-[slot=button-group]:rounded-lg",
        "icon-lg": "size-9",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

export interface ButtonProps extends ButtonPrimitive.Props, VariantProps<typeof buttonVariants> {
  tone?: "primary" | "secondary" | "quiet" | "gold" | "inverse"
  icon?: React.ReactNode
  iconRight?: React.ReactNode
  block?: boolean
}

function Button({
  className,
  variant,
  tone,
  size = "md",
  icon,
  iconRight,
  block,
  children,
  ...props
}: ButtonProps) {
  const activeVariant = tone || variant || "default"
  return (
    <ButtonPrimitive
      data-slot="button"
      className={cn(
        buttonVariants({ variant: activeVariant as any, size, className }),
        block && "w-full"
      )}
      {...props}
    >
      {icon}
      {children}
      {iconRight}
    </ButtonPrimitive>
  )
}

export { Button, buttonVariants }
